sys_variable_value.value:
(function execute(inputs, outputs) {

    var currentRecord = inputs.currentRecord;

    gs.info('***Contratos Current: ' + currentRecord);

var companycode = currentRecord.variables.company_code.getDisplayValue();
var contractNumber = currentRecord.variables.numero_da_solicitacao_original.getDisplayValue();

var validade = currentRecord.variables.data_de_inicio_do_aditivo.getDisplayValue();
var fomattedDate = formatDateToDDMMYYYY(validade);

var myobj = {
  "CompanyCode": companycode,
  "ContractNumber": contractNumber,
  "ContractEndDate": "2026-01-01", //devo enviar?       
  "MonetaryCorrectionIndex": "IPCA", //devo enviar?  

  "BaseYear": "1993", //padrão?
  "BusinessPartners": [
    {
      "BPNumber": "10007392",
      "BPRoleCode": "TR0600", //Locatario code
      "BPValidTo": "2024-12-31" //mudar desse
    },
    {
      "BPNumber": "10023528",
      "BPRoleCode": "TR0600",      
      "BPValidFrom": fomattedDate  //mudar pra esse
    }
  ],
  "TermPayments": [
    {
      "TermNumber" : "",
      "BPNumber": "10007392",
      "ValidFrom": "2022-01-01",
      "ValidTo": "2024-12-31"
    },
    {
      "TermNumber" : "",
      "BPNumber": "10023528",
      "ValidFrom": fomattedDate
    }
  ],
  "TermWithHoldingTaxes": [
    {
      "TermNumber": "",
      "TermText": "LOCATÁRIO",
      "BPNumber": "10007392",
      "ValidFrom": "2022-01-01",
      "ValidTo": "2024-12-31"
    },
    {
      "TermNumber": "",
      "TermText": "LOCATÁRIO",
      "BPNumber": "10023528",
      "ValidFrom": fomattedDate
    }
  ]  
};

function formatDateToDDMMYYYY(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}
    

    gs.info('***Contratos Output: ' + JSON.stringify(myobj));
    outputs.myobj = JSON.stringify(myobj);

})(inputs, outputs);

